P.t = function(zh, en){
  var k = P.pair[zh + '\u0001' + en]; if (k !== undefined) return k;
  var d = P.dict[en]; if (d !== undefined) return d;
  for (var i = 0; i < P.rules.length; i++){ var m = P.rules[i][0].exec(en); if (m) return P.rules[i][1](m); }
  return en;
};
